PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL DEFAULT '',student_number TEXT NOT NULL DEFAULT '');
CREATE TABLE challenges(id TEXT PRIMARY KEY,email TEXT NOT NULL,digest TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL DEFAULT 0);
CREATE INDEX challenge_email ON challenges(email);
CREATE TABLE sessions(digest TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE classes(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,code TEXT NOT NULL UNIQUE);
CREATE TABLE members(class_id TEXT NOT NULL REFERENCES classes(id),user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending',PRIMARY KEY(class_id,user_id));
CREATE TABLE progress(class_id TEXT NOT NULL,user_id TEXT NOT NULL,notes TEXT NOT NULL,checks TEXT NOT NULL,version INTEGER NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(class_id,user_id),FOREIGN KEY(class_id,user_id) REFERENCES members(class_id,user_id));
CREATE TABLE keys(id TEXT PRIMARY KEY,digest TEXT UNIQUE NOT NULL,class_id TEXT NOT NULL REFERENCES classes(id),label TEXT NOT NULL,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,class_id TEXT,created INTEGER NOT NULL);
